create table public.company_members (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role_key text not null default 'employee', status text not null default 'active' check (status in ('active','invited','suspended')), created_at timestamptz not null default now(), unique(company_id,user_id));`ncreate index company_members_user_idx on public.company_members(user_id, company_id);`nalter table public.company_members enable row level security;`ncreate or replace function public.is_company_member(target_company_id uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.company_members m where m.company_id = target_company_id and m.user_id = auth.uid() and m.status = 'active'); $$;`ncreate policy company_members_self_read on public.company_members for select using (user_id = auth.uid() or public.is_company_member(company_id));